37	    /// Creates a new [`TestRunner`] with the given [`TestConfig`].
38	    pub fn new(mut config: TestConfig) -> anyhow::Result<Self> {
39	        let test_specific_temp_dir = TempDir::new("sdk-tests")?;
40	        let gateway_listen_address = listen_address()?;
41	        let gateway_endpoint = Url::parse(&format!("http://{}/graphql", gateway_listen_address))?;
42	
43	        let mut mock_subgraphs = Vec::new();
44	        let mut subgraphs = Subgraphs::default();
45	
46	        for subgraph in config.mock_subgraphs.drain(..) {
47	            subgraphs.ingest_str(subgraph.sdl(), subgraph.name(), subgraph.url().as_str())?;
48	            mock_subgraphs.push(subgraph.start());
49	        }
50	
51	        let federated_graph = graphql_composition::compose(&subgraphs).into_result().unwrap();
52	        let federated_graph = graphql_federated_graph::render_federated_sdl(&federated_graph)?;
53	
54	        Ok(Self {
55	            http_client: reqwest::Client::new(),
56	            config,
57	            gateway_handle: None,
58	            gateway_listen_address,
59	            gateway_endpoint,
60	            test_specific_temp_dir,
61	            _mock_subgraphs: mock_subgraphs,
62	            federated_graph,
63	        })
64	    }
