66	    /// Starts the gateway process together with the configured subgraphs.
67	    ///
68	    /// This method:
69	    /// 1. Builds or uses the provided extension
70	    /// 2. Creates temporary config and schema files
71	    /// 3. Launches the gateway process with the appropriate arguments
72	    ///
73	    /// The gateway process will continue running until the [`TestRunner`] is dropped.
74	    ///
75	    /// # Errors
76	    ///
77	    /// Will return an error if:
78	    /// - Extension building fails
79	    /// - Config file creation fails
80	    /// - Schema file creation fails
81	    /// - Gateway process fails to start
82	    #[must_use]
83	    pub async fn start_servers(&mut self) -> anyhow::Result<()> {
84	        let extension_path = self.build_extension()?;
85	        let extension_path = extension_path.to_string_lossy();
86	
87	        let extension_toml_path = std::env::current_dir()?.join("extension.toml");
88	        let extension_toml = std::fs::read_to_string(&extension_toml_path)?;
89	        let extension_toml: ExtensionToml = toml::from_str(&extension_toml)?;
90	        let extension_name = extension_toml.extension.name;
91	
92	        let config_path = self.test_specific_temp_dir.path().join("grafbase.toml");
93	        let schema_path = self.test_specific_temp_dir.path().join("federated-schema.graphql");
94	        let config = &self.config.gateway_configuration;
95	        let enable_stdout = !self.config.enable_stderr;
96	        let enable_stderr = !self.config.enable_stderr;
97	        let enable_networking = self.config.enable_networking;
98	        let enable_environment_variables = self.config.enable_environment_variables;
99	        let max_pool_size = self.config.max_pool_size.unwrap_or(100);
100	
101	        let config = indoc::formatdoc! {r#"
102	            [extensions.{extension_name}]
103	            path = "{extension_path}"
104	            stdout = {enable_stdout}
105	            stderr = {enable_stderr}
106	            networking = {enable_networking}
107	            environment_variables = {enable_environment_variables}
108	            max_pool_size = {max_pool_size}
109	
110	            {config}
111	        "#};
112	
113	        println!("{config}");
114	
115	        std::fs::write(&config_path, config.as_bytes())?;
116	        std::fs::write(&schema_path, self.federated_graph.as_bytes())?;
117	
118	        let args = &[
119	            "--listen-address",
120	            &self.gateway_listen_address.to_string(),
121	            "--config",
122	            &config_path.to_string_lossy(),
123	            "--schema",
124	            &schema_path.to_string_lossy(),
125	        ];
126	
127	        let mut expr = duct::cmd(&self.config.gateway_path, args);
128	
129	        if !self.config.enable_stderr {
130	            expr = expr.stderr_null();
131	        }
132	
133	        if !self.config.enable_stdout {
134	            expr = expr.stdout_null();
135	        }
136	
137	        self.gateway_handle = Some(expr.start()?);
138	
139	        while !self.check_gateway_health().await? {
140	            std::thread::sleep(Duration::from_millis(100));
141	        }
142	
143	        Ok(())
144	    }
145	
146	    async fn check_gateway_health(&self) -> anyhow::Result<bool> {
147	        let url = self.gateway_endpoint.join("/health")?;
148	
149	        let Ok(result) = self.http_client.get(url).send().await else {
150	            return Ok(false);
151	        };
152	
153	        let result = result.error_for_status().is_ok();
154	
155	        Ok(result)
156	    }
157	
158	    fn build_extension(&mut self) -> anyhow::Result<PathBuf> {
159	        if let Some(path) = self.config.extension_path.as_ref() {
160	            return Ok(path.canonicalize()?);
161	        }
162	
163	        // Only one test can build the extension at a time. The others must
164	        // wait.
165	        let mut lock_file = fslock::LockFile::open(".build.lock")?;
166	        lock_file.lock()?;
167	        let args = &["extension", "build", "--debug"];
168	        let mut expr = duct::cmd(&self.config.cli_path, args);
169	
170	        if !self.config.enable_stdout {
171	            expr = expr.stdout_null();
172	        }
173	
174	        if !self.config.enable_stderr {
175	            expr = expr.stderr_null();
176	        }
177	
178	        expr.run()?;
179	        lock_file.unlock()?;
180	
181	        Ok(std::env::current_dir()?.join("build"))
182	    }
