56	pub(super) fn execute(cmd: ExtensionInitCommand) -> anyhow::Result<()> {
57	    if cmd.path.exists() {
58	        anyhow::bail!("destination '{}' already exists", cmd.path.to_string_lossy());
59	    }
60	
61	    std::fs::create_dir_all(&cmd.path)?;
62	
63	    let extension_name = init_cargo_toml(&cmd.path)?;
64	    init_extension_toml(&cmd.path, cmd.r#type, &extension_name)?;
65	
66	    if cmd.r#type == ExtensionType::Resolver {
67	        init_definitions_graphql(&cmd.path, &extension_name)?;
68	    }
69	
70	    init_rust_files(&cmd.path, cmd.r#type, &extension_name)?;
71	    init_gitignore(&cmd.path)?;
72	
73	    Ok(())
74	}
