        if !self.config.enable_stdout {
            expr = expr.stdout_null();
        }

        if !self.config.enable_stderr {
            expr = expr.stderr_null();
        }

        expr.run()?;
        lock_file.unlock()?;

        Ok(std::env::current_dir()?.join("build"))
    }

